int256 indexed orderID, address indexed receiver, uint256 amount, uint256 serviceFee, uint256 gasFee ); event LogVaultOut( address indexed token, address indexed from, uint256 indexed orderID, uint256 amount, address vault, bytes order ); event LogVaultCall( address indexed target, uint256 amount, bool success, bytes reason ); constructor(uint256 _id_prefix, address _lp, address _wNative) { _liquidpool = _lp; _paused = false; _orderID = _id_prefix * (10 ** 9); wNATIVE = _wNative; } receive() external payable {} fallback() external payable {} modifier whenNotPaused() { require(!_paused, "MP: paused"); _; } function chainID() public view returns (uint) { return block.chainid; } function setLiquidpool(address _lp) external onlyOwner { _liquidpool = _lp; } function setWrapNative(address _wNative) external onlyOwner { wNATIVE = _wNative; } function needWrapNative() internal view returns (bool) { return wNATIVE != address(0); } function liquidpool() internal view returns (address) { if (_liquidpool != address(0)) { return _liquidpool; } return address(this); } function pause() external onlyOwner { _paused = true; emit Paused(_msgSender()); } function unpause() external onlyOwner { _paused = false; emit Unpaused(_msgSender()); } function _isSelfLiquidpool() internal view returns (bool) { return address(this) == liquidpool(); } function isUUIDCompleted(uint256 uuid) external view returns (bool) { return completedOrder[uuid]; } function _registerOrder(uint256 uuid) internal { require(!completedOrder[uuid], "MP: already completed"); completedOrder[uuid] = true; } function _balanceOf(address receiveToken) internal view returns (uint256) { uint256 _balance; if (receiveToken == NATIVE) { if (needWrapNative()) { _balance = IERC20(wNATIVE).balanceOf(liquidpool()); } else { _balance = address(this).balance; } } else { _balance = IERC20(receiveToken).balanceOf(liquidpool()); } return _balance; } function _balanceOfSelf( address receiveToken ) internal view returns (uint256) { uint256 _balance; if (receiveToken == NATIVE) { _balance = address(this).balance; } else { _balance = IERC20(receiveToken).balanceOf(address(this)); } return _balance; } function _checkVaultOut( address tokenAddr, uint256 amount, bytes calldata order ) internal pure { require(tokenAddr != address(0), "MP: tokenAddress is invalid"); require(amount > 0, "MP: amount is 0"); require(order.length > 0, "MP: order is empty"); } function vaultOut( address tokenAddr, uint256 amount, bool burnable, bytes calldata order ) external payable nonReentrant whenNotPaused { _checkVaultOut(tokenAddr, amount, order); if (tokenAddr == NATIVE) { require(amount == msg.value, "MP: amount is invalid"); if (needWrapNative()) { uint256 old = IERC20(wNATIVE).balanceOf(address(this)); IWrapToken(wNATIVE).deposit{value: msg.value}(); uint256 val = IERC20(wNATIVE).balanceOf(address(this)); require(val - old == amount, "MP: warp token dismatch"); if (!_isSelfLiquidpool()) { IERC20(wNATIVE).safeTransfer(_liquidpool, amount); } } else { if (!_isSelfLiquidpool()) { TransferHelper.safeTransferNative(_liquidpool, amount); } } } else if (burnable) { uint256 old = IERC20(tokenAddr).balanceOf(_msgSender()); IMintBurnToken(tokenAddr).burn(_msgSender(), amount); uint256 val = IERC20(tokenAddr).balanceOf(_msgSender()); require(val == old - amount, "MP: burn failed"); } else { IERC20(tokenAddr).safeTransferFrom( _msgSender(), liquidpool(), amount ); } _orderID++; emit LogVaultOut( tokenAddr, _msgSender(), _orderID, amount, burnable ? address(0) : liquidpool(), order ); } function swap( address tokenAddr, uint256 amount, address target, address receiveToken, address receiver, uint256 minAmount, bytes calldata callData, bytes calldata order ) external payable nonReentrant whenNotPaused { _checkVaultOut(tokenAddr, amount, order); require( target != address(this) && target != address(0), "MP: target is invalid" ); require(callData.length > 0, "MP: calldata is empty"); require(receiveToken != address(0), "MP: receiveToken is empty"); require(receiver != address(0), "MP: receiver is empty"); require(minAmount > 0, "MP: minAmount is empty"); uint256 old_balance = _balanceOfSelf(receiveToken); if (tokenAddr == NATIVE) { require(amount == msg.value, "MP: amount is invalid"); target.functionCallWithValue( callData, amount, "MP: CallWithValue failed" ); } else { IERC20(tokenAddr).safeTransferFrom( _msgSender(), address(this), amount ); if (IERC20(tokenAddr).allowance(address(this), target) < amount) { IERC20(tokenAddr).safeApprove(target, MAX_UINT256); } target.functionCall(callData, "MP: FunctionCall failed"); } uint256 _amountOut = 0; uint256 new_balance = _balanceOfSelf(receiveToken); require( new_balance > old_balance, "MP: receive amount should above zero" ); _amountOut = new_balance - old_balance; require(_amountOut >= minAmount, "MP: receive amount not enough"); if (receiveToken == NATIVE) { TransferHelper.safeTransferNative(receiver, _amountOut); } else { IERC20(receiveToken).safeTransfer(receiver, _amountOut); } _orderID++; emit LogVaultOut( receiveToken, _msgSender(), _orderID, _amountOut, receiver, order ); } function vaultIn( uint256 orderID, address receiveToken, address receiver, bool burnable, uint256 amount ) external onlyController whenNotPaused { require(orderID > 0, "MP: orderID empty"); require(receiver != address(0), "MP: receiver invaild"); require(amount > 0, "MP: amount is empty"); if (!burnable) { require( _balanceOf(receiveToken) >= amount, "MP: insufficient balance" ); } _registerOrder(orderID); if (receiveToken == NATIVE) { if (needWrapNative()) { if (_isSelfLiquidpool()) { IERC20(wNATIVE).safeTransfer(receiver, amount); } else { IERC20(wNATIVE).safeTransferFrom( liquidpool(), receiver, amount ); } } else { TransferHelper.safeTransferNative(receiver, amount); } } else if (burnable) { uint256 old = IERC20(receiveToken).balanceOf(receiver); IMintBurnToken(receiveToken).mint(receiver, amount); uint256 val = IERC20(receiveToken).balanceOf(receiver); require(val =