sult); } function withdrawFee( address token, address receiver, uint256 amount ) external onlyOwner { if (token == NATIVE) { uint256 balance = address(this).balance; uint256 tmp = balance > amount ? amount : balance; TransferHelper.safeTransferNative(receiver, tmp); } else { uint256 balance = IERC20(token).balanceOf(address(this)); uint256 tmp = balance > amount ? amount : balance; IERC20(token).safeTransfer(receiver, tmp); } } function mintTo( address tokenAddr, address receiver, uint256 amount ) external onlyController { uint256 old = IERC20(tokenAddr).balanceOf(receiver); IMintBurnToken(tokenAddr).mint(receiver, amount); uint256 val = IERC20(tokenAddr).balanceOf(receiver); require(val == old + amount, "MP: mint failed"); } bytes4 constant CONTROLLER = 0xf77c4791; bytes4 constant IS_CONTROLLER = 0xb429afeb; function isMinter(address _contract) external view returns (bool) { (bool success, address result) = _getMinter(_contract); if (success && (result == address(this))) { return true; } (bool success1, bool ok) = _isMinter(_contract, address(this)); if (success1 && ok) { return true; } return false; } function isMinterWithData( address _contract, bytes memory data, bytes memory expectRes ) external view returns (bool) { (bool success, address result) = _getMinter(_contract); if (success && (result == address(this))) { return true; } (bool success1, bool ok) = _isMinter(_contract, address(this)); if (success1 && ok) { return true; } if (data.length > 0) { (bool success2, bytes memory returndata) = _contract.staticcall( data ); return success2 && bytesEqual(returndata, expectRes); } return false; } function _getMinter( address _contract ) internal view returns (bool, address) { (bool success, bytes memory returndata) = _contract.staticcall( abi.encodeWithSelector(CONTROLLER) ); return (success, bytesToAddress(returndata)); } function _isMinter( address _contract, address _target ) internal view returns (bool, bool) { (bool success, bytes memory returndata) = _contract.staticcall( abi.encodeWithSelector(IS_CONTROLLER, _target) ); (bool ok, uint res) = toUint(returndata); return (success && ok, res == 1); } function toUint(bytes memory bs) internal pure returns (bool, uint) { if (bs.length < 32) { return (false, 0); } uint x; assembly { x := mload(add(bs, add(0x20, 0))) } return (true, x); } function bytesToAddress( bytes memory bys ) internal pure returns (address addr) { assembly { addr := mload(add(bys, 32)) } } function bytesEqual( bytes memory a, bytes memory b ) public pure returns (bool) { return keccak256(a) == keccak256(b); } }

